const http = (options) => this.helpers.httpRequest(options);
const PRICING = JSON.parse($env.MODEL_PRICING || '{}');
const TELEGRAM_API = `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}`;

const telegram = (method, body) => http({ method: 'POST', url: `${TELEGRAM_API}/${method}`, body, json: true });
const say = (chatId, text, extra = {}) => telegram('sendMessage', { chat_id: chatId, text, ...extra });

const costOf = (model, tokensIn, tokensOut) => {
  const [priceIn, priceOut] = PRICING[model] || [0, 0];
  return Number(((tokensIn * priceIn + tokensOut * priceOut) / 1e6).toFixed(6));
};

async function callClaude(model, system, mime, b64, schema, maxTokens) {
  const media = mime === 'application/pdf' ? 'document' : 'image';
  const res = await http({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': $env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
    body: {
      model,
      max_tokens: maxTokens,
      system,
      tools: [{ name: 'record', description: 'Record the result', input_schema: schema }],
      tool_choice: { type: 'tool', name: 'record' },
      messages: [{
        role: 'user',
        content: [
          { type: media, source: { type: 'base64', media_type: mime, data: b64 } },
          { type: 'text', text: 'Process this document.' },
        ],
      }],
    },
    json: true,
    timeout: 90000,
  });
  const block = (res.content || []).find((c) => c.type === 'tool_use');
  if (!block) throw new Error('model returned no structured output');
  return { data: block.input, tokensIn: res.usage.input_tokens, tokensOut: res.usage.output_tokens };
}

async function chatCompletion(url, key, body) {
  const res = await http({
    method: 'POST',
    url,
    headers: { Authorization: `Bearer ${key}` },
    body,
    json: true,
    timeout: 90000,
  });
  return {
    data: JSON.parse(res.choices[0].message.content),
    tokensIn: res.usage.prompt_tokens,
    tokensOut: res.usage.completion_tokens,
  };
}

async function callOpenAI(model, system, mime, b64, schema, maxTokens) {
  const dataUrl = `data:${mime};base64,${b64}`;
  const part = mime === 'application/pdf'
    ? { type: 'file', file: { filename: 'document.pdf', file_data: dataUrl } }
    : { type: 'image_url', image_url: { url: dataUrl } };
  return chatCompletion('https://api.openai.com/v1/chat/completions', $env.OPENAI_API_KEY, {
    model,
    max_tokens: maxTokens,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: [part, { type: 'text', text: 'Process this document.' }] },
    ],
    response_format: { type: 'json_schema', json_schema: { name: 'record', schema } },
  });
}

// DeepSeek only offers JSON mode, so the schema goes into the prompt and validation enforces it
async function callDeepSeek(model, system, mime, b64, schema, maxTokens) {
  if (mime === 'application/pdf') throw new Error('DeepSeek does not accept PDF input');
  const instruction = `${system}\n\nRespond with a single JSON object that matches this JSON schema:\n${JSON.stringify(schema)}`;
  return chatCompletion('https://api.deepseek.com/chat/completions', $env.DEEPSEEK_API_KEY, {
    model,
    max_tokens: maxTokens,
    messages: [
      { role: 'system', content: instruction },
      {
        role: 'user',
        content: [
          { type: 'image_url', image_url: { url: `data:${mime};base64,${b64}` } },
          { type: 'text', text: 'Process this document.' },
        ],
      },
    ],
    response_format: { type: 'json_object' },
  });
}

const providerFor = (model) => (model.startsWith('claude') ? callClaude : model.startsWith('deepseek') ? callDeepSeek : callOpenAI);

// Tries the primary model twice, then the fallback model once
async function runLLM(step, system, mime, b64, schema, maxTokens) {
  const models = [$env.PRIMARY_MODEL, $env.PRIMARY_MODEL, $env.FALLBACK_MODEL].filter(Boolean);
  const usage = [];
  let lastError = 'no model configured';
  for (const model of models) {
    const started = Date.now();
    try {
      const r = await providerFor(model)(model, system, mime, b64, schema, maxTokens);
      usage.push({
        step, model, tokens_in: r.tokensIn, tokens_out: r.tokensOut,
        cost_usd: costOf(model, r.tokensIn, r.tokensOut), latency_ms: Date.now() - started,
      });
      return { data: r.data, model, usage };
    } catch (e) {
      lastError = e.message;
      usage.push({ step, model, tokens_in: 0, tokens_out: 0, cost_usd: 0, latency_ms: Date.now() - started });
    }
  }
  return { error: lastError, usage };
}

const fs = require('fs');
const SCHEMAS = {"invoice": {"type": "object", "additionalProperties": false, "required": ["invoice_number", "date", "vendor", "line_items", "subtotal", "tax", "total"], "properties": {"invoice_number": {"type": "string", "minLength": 1}, "date": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"}, "vendor": {"type": "string", "minLength": 1}, "line_items": {"type": "array", "minItems": 1, "items": {"type": "object", "additionalProperties": false, "required": ["description", "quantity", "unit_price", "amount"], "properties": {"description": {"type": "string", "minLength": 1}, "quantity": {"type": "number", "exclusiveMinimum": 0}, "unit_price": {"type": "number", "minimum": 0}, "amount": {"type": "number", "minimum": 0}}}}, "subtotal": {"type": "number", "minimum": 0}, "tax": {"type": "number", "minimum": 0}, "total": {"type": "number", "minimum": 0}}}, "ktp": {"type": "object", "additionalProperties": false, "required": ["nik", "name", "birth_date", "address", "gender"], "properties": {"nik": {"type": "string", "pattern": "^\\d{16}$"}, "name": {"type": "string", "minLength": 1}, "birth_date": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"}, "address": {"type": "string", "minLength": 1}, "gender": {"type": "string", "enum": ["male", "female"]}}}, "spk": {"type": "object", "additionalProperties": false, "required": ["spk_number", "customer_name", "model", "variant", "color", "price", "payment_method"], "properties": {"spk_number": {"type": "string", "minLength": 1}, "customer_name": {"type": "string", "minLength": 1}, "model": {"type": "string", "minLength": 1}, "variant": {"type": "string", "minLength": 1}, "color": {"type": "string", "minLength": 1}, "price": {"type": "number", "exclusiveMinimum": 0}, "payment_method": {"type": "string", "enum": ["cash", "credit", "leasing"]}}}};
const PROMPTS = {"invoice": "You extract structured data from an Indonesian vendor invoice and call the record tool with the result.\n\nRules:\n- Copy values exactly as printed. Never guess or compute a value that is not on the document.\n- Dates must be ISO format YYYY-MM-DD, whatever format is printed.\n- Money values are plain integers in rupiah with no currency symbol or separators. Indonesian notation uses a dot as the thousands separator, so \"1.250.000\" is 1250000.\n- invoice_number is the document number as printed, including prefixes and slashes.\n- line_items lists every row of the item table in order. quantity, unit_price and amount are read from the row, not recalculated.\n- subtotal, tax and total are the printed summary values.", "ktp": "You extract structured data from an Indonesian ID card (KTP) and call the record tool with the result.\n\nRules:\n- Copy values exactly as printed. Never guess a digit; read the NIK digit by digit.\n- nik is the 16 digit number printed next to \"NIK\", digits only.\n- name is printed in uppercase; keep it that way.\n- birth_date is the date part of \"Tempat/Tgl Lahir\" as ISO format YYYY-MM-DD. Ignore the birth place.\n- address is the street line printed after \"Alamat\", without RT/RW, village or district.\n- gender is \"male\" for LAKI-LAKI and \"female\" for PEREMPUAN.", "spk": "You extract structured data from an Indonesian vehicle sales order (SPK) and call the record tool with the result.\n\nRules:\n- Copy values exactly as printed. Never guess or fill in a value that is not on the document.\n- spk_number is the document number as printed, including prefixes and slashes.\n- customer_name is the name printed after \"Nama Pemesan\".\n- model, variant and color are copied as printed.\n- price is the \"Harga OTR\" value as a plain integer in rupiah with no symbol or separators. \"Rp 245.000.000\" is 245000000.\n- payment_method is \"cash\" for Tunai, \"credit\" for Kredit and \"leasing\" for Leasing."};

const doc = $input.first().json;
if (doc.status !== 'received') return [{ json: doc }];

const b64 = fs.readFileSync(doc.file_path).toString('base64');
const out = await runLLM('extract', PROMPTS[doc.doc_type], doc.mime, b64, SCHEMAS[doc.doc_type], 2048);
doc.usage = (doc.usage || []).concat(out.usage);

if (out.error) {
  doc.status = 'failed';
  doc.reason = `Extraction failed: ${out.error}`;
  return [{ json: doc }];
}

doc.extraction = out.data;
doc.model = out.model;
doc.status = 'extracted';
return [{ json: doc }];
